// 067H / G51 — HubSpot-Baseline-Mapper: paginierte Seiten zusammenführen,
// Stages mappen (Unbekannte in Quarantäne, NIEMALS still LOST), Integrität
// prüfen und Envelope mit Portal/Zeit/Quelle/Hash erzeugen.
//
// Pull-Konfiguration (Spiegel der Fetch-Nodes):
// - Seiten über paging.next.after bis zur Erschöpfung (kein 100er-Limit).
// - 429-Backoff: Fetch-Retry (5 Versuche, 2 s Abstand) + Wait-Nodes (1 s).
// - Abort: Workflow-Abbruch (AbortSignal-Semantik von n8n am Leben erhalten,
//   keine schwalbenden Catch-Blöcke um Fetch-Aufrufe).
// - Maximallaufzeit: Workflow-Settings executionTimeout (300 s).
const PULL_CONFIG = { maxPages: 50, backoffMs: 1000, maxRetries429: 5, maxRuntimeMs: 120000 };
const PORTAL_ID = 148979005; // Je Portal beim Einrichten setzen (HubSpot-Portal-ID).
const PERIOD_START = '2026-01-01';

// Mapping Stage Table Definition (Spiegel von hubspot-stage-map.json).
const STAGE_MAP = {
  appointmentscheduled: 'LEAD',
  qualifiedtobuy: 'QUALIFIED_LEAD',
  presentationscheduled: 'PITCH_DEMO',
  decisionmakerboughtin: 'PROPOSAL',
  contractsent: 'CLOSING',
  closedwon: 'WON',
  closedlost: 'LOST',
  'Termin vereinbart': 'LEAD',
  'Für Kauf qualifiziert': 'QUALIFIED_LEAD',
  'Präsentation vereinbart': 'PITCH_DEMO',
  'Entscheidungsträger hat zugestimmt': 'PROPOSAL',
  'Vertrag gesendet': 'CLOSING',
  'Abgeschlossen und gewonnen': 'WON',
  'Abgeschlossen und verloren': 'LOST'
};

function allResults(nodeName) {
  const pages = $(nodeName).all().map((i) => i.json);
  if (pages.length > PULL_CONFIG.maxPages) {
    throw new Error(`HubSpot-Baseline: Seitenlimit ${PULL_CONFIG.maxPages} überschritten.`);
  }
  return pages.flatMap((p) => p.results || []);
}

function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value) ?? 'null';
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(',')}]`;
  const keys = Object.keys(value).sort();
  return `{${keys.map((k) => `${JSON.stringify(k)}:${stableStringify(value[k])}`).join(',')}}`;
}

function contentHashOf(obj) {
  const str = stableStringify(obj);
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h + str.charCodeAt(i)) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

const rawCompanies = allResults('Fetch Companies');
const rawContacts = allResults('Fetch Contacts');
const rawDeals = allResults('Fetch Deals');

const companies = [];
const companyIds = new Set();
let companiesErrors = 0;

for (const c of rawCompanies) {
  const id = String(c.id || c.properties?.hs_object_id || '');
  const name = String(c.properties?.name || '').trim();
  if (!id || !name) {
    companiesErrors++;
    continue;
  }
  companyIds.add(id);
  companies.push({
    id,
    name,
    domain: c.properties?.domain || undefined,
    industry: c.properties?.industry || 'Allgemein',
    city: c.properties?.city || 'Unbekannt',
    postalCode: c.properties?.zip || undefined,
    employeeCount: Number(c.properties?.numberofemployees) || 1,
    createdAt: c.properties?.createdate || c.createdAt || undefined
  });
}

const contacts = [];
let contactsErrors = 0;
let contactsMatched = 0;

for (const ct of rawContacts) {
  const id = String(ct.id || ct.properties?.hs_object_id || '');
  let companyId = ct.properties?.associatedcompanyid ? String(ct.properties.associatedcompanyid) : '';
  if (!companyId && ct.associations?.companies?.results?.length > 0) {
    companyId = String(ct.associations.companies.results[0].id);
  }
  if (!id || !companyId || !companyIds.has(companyId)) {
    contactsErrors++;
    continue;
  }
  contactsMatched++;
  contacts.push({
    id,
    companyId,
    email: ct.properties?.email || `contact-${id}@leadpilot.internal`,
    firstName: ct.properties?.firstname || '',
    lastName: ct.properties?.lastname || '',
    jobTitle: ct.properties?.jobtitle || undefined,
    name: `${ct.properties?.firstname || ''} ${ct.properties?.lastname || ''}`.trim() || undefined
  });
}

const importedFunnelDeals = [];
let dealsErrors = 0;
let quarantinedStages = 0;

for (const d of rawDeals) {
  const id = String(d.id || d.properties?.hs_object_id || '');
  const rawStage = String(d.properties?.dealstage || '').trim();
  const mapped = STAGE_MAP[rawStage] || (rawStage ? STAGE_MAP[rawStage.toLowerCase()] : undefined);
  let companyId = '';
  if (d.associations?.companies?.results?.length > 0) {
    companyId = String(d.associations.companies.results[0].id);
  }
  if (!id) {
    dealsErrors++;
    continue;
  }
  if (!mapped) {
    // Quarantäne statt still LOST: unbekannte Stage bleibt sichtbar.
    quarantinedStages++;
    importedFunnelDeals.push({
      id,
      dealName: String(d.properties?.dealname || 'Unbenannt'),
      stage: 'QUARANTINED',
      quarantineReason: rawStage,
      amount: Number(d.properties?.amount) || 0,
      closeDate: d.properties?.closedate || '',
      pipeline: String(d.properties?.pipeline || 'default'),
      companyId: companyId || undefined
    });
    continue;
  }
  importedFunnelDeals.push({
    id,
    dealName: String(d.properties?.dealname || 'Unbenannt'),
    stage: mapped,
    amount: Number(d.properties?.amount) || 0,
    closeDate: d.properties?.closedate || '',
    pipeline: String(d.properties?.pipeline || 'default'),
    companyId: companyId || undefined
  });
}

const generatedAt = new Date().toISOString();
const counts = {
  companies: companies.length,
  contacts: contacts.length,
  deals: importedFunnelDeals.length,
  activities: 0
};
const audit = {
  companiesLoaded: rawCompanies.length,
  companiesValid: companies.length,
  companiesErrors,
  contactsLoaded: rawContacts.length,
  contactsValid: contacts.length,
  contactsMatched,
  contactsErrors,
  dealsLoaded: rawDeals.length,
  dealsValid: importedFunnelDeals.length,
  dealsErrors,
  quarantinedStages
};

const envelope = {
  version: `hubspot-${generatedAt.slice(0, 10)}`,
  generatedAt,
  generator: 'n8n-hubspot-pull',
  sourceSystem: 'hubspot',
  hubspotPortalId: PORTAL_ID,
  periodStart: PERIOD_START,
  counts,
  companies,
  contacts,
  importedFunnelDeals,
  activities: [],
  audit
};
envelope.contentHash = contentHashOf({
  version: envelope.version,
  sourceSystem: envelope.sourceSystem,
  hubspotPortalId: envelope.hubspotPortalId,
  periodStart: envelope.periodStart,
  counts: envelope.counts,
  companies: envelope.companies,
  contacts: envelope.contacts,
  importedFunnelDeals: envelope.importedFunnelDeals,
  activities: envelope.activities,
  audit: envelope.audit
});

return [{ json: envelope }];

// 067H / G51 — Importfreigabe: Counts, Referenzen, Pflichtfelder und
// Zeitraum müssen konsistent sein, sonst kein Baseline-Artefakt.
const envelope = $input.first().json;

if (!envelope.companies || envelope.companies.length === 0) {
  throw new Error('HubSpot Baseline Assert Error: Keine Companies gefunden.');
}
if (!envelope.importedFunnelDeals || envelope.importedFunnelDeals.length === 0) {
  throw new Error('HubSpot Baseline Assert Error: Keine Deals gefunden.');
}

const companyIds = new Set(envelope.companies.map((c) => c.id));
for (const c of envelope.companies) {
  if (!c.id || !c.name) {
    throw new Error('HubSpot Baseline Assert Error: Company ohne id/name.');
  }
}
for (const ct of envelope.contacts) {
  if (!companyIds.has(ct.companyId)) {
    throw new Error(`HubSpot Baseline Assert Error: Dangling Contact ${ct.id} -> Company ${ct.companyId}`);
  }
}

const KNOWN_STAGES = new Set(['LEAD', 'QUALIFIED_LEAD', 'PITCH_DEMO', 'PROPOSAL', 'CLOSING', 'WON', 'LOST', 'QUARANTINED']);
for (const d of envelope.importedFunnelDeals) {
  if (!d.id || !d.dealName || !d.pipeline || !Number.isFinite(d.amount)) {
    throw new Error(`HubSpot Baseline Assert Error: Deal ohne Pflichtfelder (${d.id}).`);
  }
  if (!KNOWN_STAGES.has(d.stage)) {
    throw new Error(`HubSpot Baseline Assert Error: Unbekannte Stage ohne Quarantäne (${d.stage}).`);
  }
  if (d.companyId && !companyIds.has(d.companyId)) {
    throw new Error(`HubSpot Baseline Assert Error: Dangling Deal ${d.id} -> Company ${d.companyId}.`);
  }
}

const periodStart = Date.parse(envelope.periodStart || '2026-01-01');
if (Number.isNaN(periodStart)) {
  throw new Error('HubSpot Baseline Assert Error: periodStart ungültig.');
}
for (const a of envelope.activities || []) {
  const t = Date.parse(a.timestamp);
  if (Number.isNaN(t) || t < periodStart || t > periodStart + 365 * 864e5) {
    throw new Error(`HubSpot Baseline Assert Error: Activity ${a.id} außerhalb des Zeitraums.`);
  }
}

for (const field of ['hubspotPortalId', 'generatedAt', 'sourceSystem', 'contentHash']) {
  if (envelope[field] === undefined || envelope[field] === null || envelope[field] === '') {
    throw new Error(`HubSpot Baseline Assert Error: Metadatum ${field} fehlt.`);
  }
}

return [{ json: envelope }];
